float lrFolds(vec2 mm,float depth,float upper,float footprint){
 // The broad paired field is independently gated below; every pair is zero
 // before footprint reaches 1.20 mm. Preserve the fine field's .34 mm cutoff.
 if(footprint>=1.20)return 0.;
 float spanMM=max(1.,mix(lrInnerBottom(vFRest.x)-lrBottom(vFRest.x),lrTop(vFRest.x)-lrInnerTop(vFRest.x),upper)*1000.);
 float spacing=1.10,cell=floor(mm.x/spacing),height=0.,tissueHeight=0.;
 float previousCenter=0.,previousAlong=0.,previousStart=0.,previousEnd=0.,previousAmplitude=0.,previousExists=0.;
 // Fine grooves keep their original bounded support. The added field is
 // restricted to the interval between two consecutive existing main curves;
 // these five cells cover every such interval intersecting the current cell.
 for(int j=-2;j<=2;j++){
  float id=cell+float(j);vec2 k=vec2(id,upper*113.+211.);
  float a=lrHash(k),b=lrHash(k+17.7),c=lrHash(k+54.1),d=lrHash(k+91.3);
  float root=(id+.12+.76*a)*spacing;
  float mainExists=step(.18,lrHash(k+121.6));
  if(mainExists>.5){
   float extent=mix(.12+.18*c,.30+.42*c,step(.42,lrHash(k+141.3)));
   float start=.035+(.92-extent)*b;
   float t=clamp((depth-start)/extent,0.,1.);
   float drift=(lrHash(k+159.7)-.5)*.72,bend=(lrHash(k+177.9)-.5)*.28;
   float center=root+drift*(t-.5)+bend*4.*t*(1.-t);
   float width=.045+.035*d,filterWidth=sqrt(width*width+footprint*footprint*.30);
   float endSoft=min(.48,max(.16,footprint/max(.05,extent*spanMM)));
   float along=smoothstep(0.,endSoft,t)*(1.-smoothstep(1.-endSoft,1.,t));
   float amplitude=(.000006+.000004*lrHash(k+193.4))*4.;
   // One bounded hypothesis: broad tissue between the same two finite main
   // curves. No new root, seed, geometry displacement or roughness field.
   if(previousExists>.5){
    float gapMM=center-previousCenter;
    float overlapMM=max(0.,min(start+extent,previousEnd)-max(start,previousStart))*spanMM;
    float safeFootprint=max(footprint,.001);
    // Conservative separate cross/along resolution gates, not an exact 2-D
    // convolution or proof of temporal anti-aliasing. Crossed or tiny gaps
    // contribute zero; along overlap must be resolvable as well.
    float resolved=smoothstep(2.,4.,gapMM/safeFootprint)*smoothstep(2.,4.,overlapMM/safeFootprint);
    float between=clamp((mm.x-previousCenter)/max(gapMM,.0001),0.,1.);
    float p=between*(1.-between);
